<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { RouterLink, useRouter } from 'vue-router'
import { useAuthenticationStore } from '../../stores/authentication/store'
import { departService } from '../../services/depart/service'
import { destinationService } from '../../services/destination/service'
import { gareService } from '../../services/gare/service'
import type { PublicProgramme } from '../../models/depart/model'
import type { PublicDestination } from '../../models/destination/model'
import type { PublicGare, PublicGareCooperative } from '../../models/gare/model'
import { localIsoDate } from '../../utils/date'

const router = useRouter()
const auth = useAuthenticationStore()
const today = localIsoDate()
const loading = ref(false)
const loadingReferences = ref(false)
const error = ref('')
const mobileMenuOpen = ref(false)
const programme = ref<PublicProgramme[]>([])
const destinations = ref<PublicDestination[]>([])
const gares = ref<PublicGare[]>([])
const total = ref(0)
const filters = reactive({ from: '', to: '', date: today, dateTo: '', gare: '', cooperative: '', passengers: '1', search: '' })
const searchErrors = reactive({ from: '', to: '', date: '', passengers: '' })

const cooperativeOptions = computed<PublicGareCooperative[]>(() => {
  const source = filters.gare ? gares.value.filter((item) => item.id === Number(filters.gare)) : gares.value
  const unique = new Map<number, PublicGareCooperative>()
  source.flatMap((item) => item.cooperatives).forEach((item) => unique.set(item.id, item))
  return [...unique.values()].sort((left, right) => left.nom.localeCompare(right.nom))
})
const featuredDepartures = computed(() => programme.value.slice(0, 6))
const tomorrow = computed(() => new Date(Date.now() + 86400000).toISOString().slice(0, 10))

function displayDate(value: string) { return new Intl.DateTimeFormat('fr-FR', { weekday: 'short', day: '2-digit', month: 'short', year: 'numeric' }).format(new Date(`${value}T00:00:00`)) }
function displayPrice(item: PublicProgramme) { return item.tarif ? `${Number(item.tarif.prix).toLocaleString('fr-FR')} ${item.tarif.devise}` : 'Tarif à confirmer' }
function statusLabel(status: PublicProgramme['statut']) { return { PROGRAMME: 'Programmé', EMBARQUEMENT: 'Embarquement', RETARDE: 'Retardé' }[status] }
function statusClass(status: PublicProgramme['statut']) { return status.toLowerCase() }
function setDate(value: 'today' | 'tomorrow') { filters.date = value === 'today' ? today : tomorrow.value }
function query() { return { from: filters.from || undefined, to: filters.to || undefined, date: filters.date || undefined, dateTo: filters.dateTo || undefined, passengers: filters.passengers, gare: filters.gare || undefined, cooperative: filters.cooperative || undefined, search: filters.search || undefined } }
function clearSearchErrors() { searchErrors.from = ''; searchErrors.to = ''; searchErrors.date = ''; searchErrors.passengers = '' }
function validateSearch() {
  clearSearchErrors()
  if (!filters.from) searchErrors.from = 'Choisissez une ville de départ.'
  if (!filters.to) searchErrors.to = 'Choisissez une destination.'
  if (!filters.date) searchErrors.date = 'Choisissez une date de départ.'
  if (!filters.passengers || Number(filters.passengers) < 1) searchErrors.passengers = 'Indiquez le nombre de passagers.'
  return !Object.values(searchErrors).some(Boolean)
}
function swapLocations() { const from = filters.from; filters.from = filters.to; filters.to = from; clearSearchErrors() }
function submitSearch() { if (!validateSearch()) { document.getElementById('search')?.scrollIntoView({ behavior: 'smooth', block: 'center' }); return }; void router.push({ name: 'search-results', query: query() }) }
function reserve(item: PublicProgramme) { void router.push({ name: 'public-booking', query: { depart_id: String(item.id) } }) }
function goToSpace() { void router.push({ name: auth.user?.role?.toLowerCase() === 'passenger' ? 'client-space' : 'home' }) }
function resetFilters() { filters.from = ''; filters.to = ''; filters.date = today; filters.dateTo = ''; filters.gare = ''; filters.cooperative = ''; filters.passengers = '1'; filters.search = ''; clearSearchErrors(); void loadProgramme() }
function chooseDestination(id: number) { filters.to = String(id); void loadProgramme(); document.getElementById('departures')?.scrollIntoView({ behavior: 'smooth' }) }
function selectGare(id: number) { filters.gare = String(id); filters.cooperative = ''; void loadProgramme(); document.getElementById('departures')?.scrollIntoView({ behavior: 'smooth' }) }

async function loadReferences() {
  loadingReferences.value = true
  try {
    const [destinationResult, gareResult] = await Promise.all([destinationService.publicList({ page: 1, page_size: 200 }), gareService.publicList({ page: 1, page_size: 100 })])
    destinations.value = destinationResult.items || []; gares.value = gareResult.items || []
  } catch (value) { console.error('[PUBLIC_REFERENCES_ERROR]', value) }
  finally { loadingReferences.value = false }
}
async function loadProgramme() {
  loading.value = true; error.value = ''
  try {
    const result = await departService.publicProgramme({ page: 1, page_size: 50, search: filters.search.trim() || undefined, date_from: filters.date || undefined, date_to: filters.dateTo || undefined, id_destination_depart: filters.from ? Number(filters.from) : undefined, id_destination_arrivee: filters.to ? Number(filters.to) : undefined, id_gare: filters.gare ? Number(filters.gare) : undefined, id_cooperative: filters.cooperative ? Number(filters.cooperative) : undefined, passagers: Number(filters.passengers) })
    programme.value = result.items || []; total.value = result.total || 0
  } catch (value) { console.error('[PUBLIC_PROGRAMME_ERROR]', value); error.value = 'Le programme est momentanément indisponible.' }
  finally { loading.value = false }
}
onMounted(() => { void Promise.all([loadReferences(), loadProgramme()]) })
</script>

<template>
  <main class="travel-home">
    <header class="travel-header"><RouterLink class="travel-brand" to="/" aria-label="Accueil Coopérative"><span class="travel-brand-mark">C</span><strong>Coopérative</strong></RouterLink><label class="global-search"><span>⌕</span><input v-model="filters.search" type="search" placeholder="Rechercher un trajet, une gare…" aria-label="Rechercher un trajet" @keyup.enter="submitSearch"></label><nav class="travel-nav" aria-label="Navigation principale"><a href="#departures">Voyages</a><a href="#destinations">Destinations</a><a href="#stations">Gares</a><a href="#guide">Guide du voyage</a></nav><div class="travel-actions"><button class="travel-menu" type="button" :aria-label="mobileMenuOpen ? 'Fermer le menu' : 'Ouvrir le menu'" :aria-expanded="mobileMenuOpen" @click="mobileMenuOpen = !mobileMenuOpen">☰</button><RouterLink class="travel-login" to="/ma-reservation">Ma réservation</RouterLink><button v-if="auth.isAuthenticated" class="travel-login" type="button" @click="goToSpace">Mon espace</button><RouterLink v-else class="travel-login" to="/login">Connexion</RouterLink><RouterLink v-if="!auth.isAuthenticated" class="travel-signup" to="/register">Créer un compte</RouterLink></div></header>
    <nav v-if="mobileMenuOpen" class="travel-mobile-nav" aria-label="Menu mobile"><a href="#departures" @click="mobileMenuOpen = false">Voyages</a><a href="#destinations" @click="mobileMenuOpen = false">Destinations</a><a href="#stations" @click="mobileMenuOpen = false">Gares</a><a href="#guide" @click="mobileMenuOpen = false">Guide du voyage</a><RouterLink to="/ma-reservation" @click="mobileMenuOpen = false">Ma réservation</RouterLink></nav>

    <section class="travel-hero"><div class="travel-hero-inner"><div class="travel-hero-copy"><p class="travel-eyebrow">LE VOYAGE COMMENCE ICI</p><h1>Partez plus loin,<br><em>simplement.</em></h1><p>Comparez les départs des coopératives, choisissez votre gare et préparez votre voyage à travers Madagascar.</p><div class="travel-hero-points"><span>✓ Programme public</span><span>✓ Places disponibles</span><span>✓ Paiement mobile money</span></div></div><div class="travel-hero-art" aria-hidden="true"><div class="art-sun"></div><div class="art-hill hill-one"></div><div class="art-hill hill-two"></div><div class="art-road"></div><div class="art-bus"><i></i><i></i><b>COOP</b></div></div></div></section>

    <section id="search" class="search-panel"><div class="search-tabs"><span class="active">Voyages</span><RouterLink v-if="auth.isAuthenticated" to="/mes-reservations">Mes réservations</RouterLink><span v-else>Réservation sans compte</span></div><form @submit.prevent="submitSearch" novalidate><div class="search-panel-heading"><div><p class="travel-eyebrow">RÉSERVER UN TRAJET</p><h2>Où souhaitez-vous aller ?</h2><button class="swap-locations" type="button" @click="swapLocations">↕ Inverser le trajet</button></div><span>Les champs marqués d’un * sont obligatoires. Une avance d’au moins 25 % est demandée pour valider la réservation.</span></div><div class="search-fields"><label :class="{ 'has-error': searchErrors.from }"><span>Départ <b>*</b></span><select v-model="filters.from" :disabled="loadingReferences" required :aria-invalid="Boolean(searchErrors.from)" aria-describedby="search-from-error"><option value="">Choisir une ville</option><option v-for="item in destinations" :key="`from-${item.id}`" :value="String(item.id)">{{ item.nom }}</option></select><small v-if="searchErrors.from" id="search-from-error" class="field-error">{{ searchErrors.from }}</small></label><label :class="{ 'has-error': searchErrors.to }"><span>Destination <b>*</b></span><select v-model="filters.to" :disabled="loadingReferences" required :aria-invalid="Boolean(searchErrors.to)" aria-describedby="search-to-error"><option value="">Choisir une ville</option><option v-for="item in destinations" :key="`to-${item.id}`" :value="String(item.id)">{{ item.nom }}</option></select><small v-if="searchErrors.to" id="search-to-error" class="field-error">{{ searchErrors.to }}</small></label><label :class="{ 'has-error': searchErrors.date }"><span>Date de départ <b>*</b></span><input v-model="filters.date" type="date" :min="today" required :aria-invalid="Boolean(searchErrors.date)" aria-describedby="search-date-error"><small v-if="searchErrors.date" id="search-date-error" class="field-error">{{ searchErrors.date }}</small></label><label :class="{ 'has-error': searchErrors.passengers }"><span>Passagers <b>*</b></span><select v-model="filters.passengers" required :aria-invalid="Boolean(searchErrors.passengers)" aria-describedby="search-passengers-error"><option v-for="count in 8" :key="count" :value="String(count)">{{ count }} {{ count === 1 ? 'passager' : 'passagers' }}</option></select><small v-if="searchErrors.passengers" id="search-passengers-error" class="field-error">{{ searchErrors.passengers }}</small></label><button class="search-submit" type="submit" :disabled="loading">{{ loading ? 'Recherche…' : 'Rechercher' }} <b>→</b></button></div><div class="quick-dates"><span>Date rapide :</span><button type="button" :class="{ active: filters.date === today }" @click="setDate('today')">Aujourd’hui</button><button type="button" :class="{ active: filters.date === tomorrow }" @click="setDate('tomorrow')">Demain</button><details><summary>Plus de filtres</summary><div class="secondary-fields"><label><span>Gare</span><select v-model="filters.gare" @change="filters.cooperative = ''"><option value="">Toutes les gares</option><option v-for="item in gares" :key="item.id" :value="String(item.id)">{{ item.nom }} · {{ item.ville }}</option></select></label><label><span>Coopérative</span><select v-model="filters.cooperative"><option value="">Toutes les coopératives</option><option v-for="item in cooperativeOptions" :key="item.id" :value="String(item.id)">{{ item.nom }}</option></select></label><label><span>Jusqu’au</span><input v-model="filters.dateTo" type="date" :min="filters.date || today"></label><label><span>Mot-clé</span><input v-model="filters.search" type="search" placeholder="Ville ou coopérative"></label><button type="button" class="reset-button" @click="resetFilters">Réinitialiser</button></div></details></div></form></section>

    <section id="departures" class="home-section departures-section"><div class="section-heading"><div><p class="travel-eyebrow">DÉPARTS DISPONIBLES</p><h2>Les prochains voyages</h2><p>Comparez l’horaire, la gare, la coopérative, le tarif et les places.</p></div><RouterLink class="outline-button" :to="{ name: 'search-results', query: query() }">Voir tous les départs <b>→</b></RouterLink></div><p v-if="error" class="home-alert" role="alert">{{ error }} <button type="button" @click="loadProgramme">Réessayer</button></p><div v-else-if="loading" class="departure-list"><div v-for="item in 3" :key="item" class="departure-skeleton"><i></i><i></i><i></i></div></div><div v-else-if="!featuredDepartures.length" class="empty-panel"><strong>Aucun départ disponible pour ces critères.</strong><span>Essayez une autre date ou élargissez votre recherche.</span><button type="button" class="outline-button" @click="resetFilters">Réinitialiser la recherche</button></div><div v-else class="departure-list"><article v-for="item in featuredDepartures" :key="item.id" class="departure-offer"><div class="offer-time"><strong>{{ item.heure_depart?.slice(0, 5) }}</strong><span>{{ displayDate(item.date_depart) }}</span></div><div class="offer-route"><div><strong>{{ item.itineraire?.destination_depart?.nom || 'Départ' }}</strong><span>Ville de départ</span></div><b>→</b><div><strong>{{ item.itineraire?.destination_arrivee?.nom || 'Destination' }}</strong><span>Destination</span></div></div><div class="offer-context"><span><small>Gare</small><strong>{{ item.gare?.nom || 'À confirmer' }}</strong><em v-if="item.gare?.ville">{{ item.gare.ville }}</em></span><span><small>Coopérative</small><strong>{{ item.cooperative?.nom || 'À confirmer' }}</strong><em><i class="status-dot" :class="statusClass(item.statut)"></i>{{ statusLabel(item.statut) }}</em></span><span><small>Disponibilité</small><strong>{{ item.places_disponibles }} place{{ item.places_disponibles > 1 ? 's' : '' }}</strong><em>sur {{ item.nombre_places }} places</em></span></div><div class="offer-price"><small>Tarif</small><strong>{{ displayPrice(item) }}</strong><button type="button" @click="reserve(item)">Voir et réserver <b>→</b></button></div></article></div></section>

    <section id="destinations" class="home-section destination-section"><div class="section-heading"><div><p class="travel-eyebrow">DESTINATIONS POPULAIRES</p><h2>Partez depuis votre ville</h2><p>Explorez les destinations desservies par les coopératives disponibles.</p></div></div><div class="destination-grid"><button v-for="item in destinations.slice(0, 6)" :key="item.id" type="button" class="destination-tile" @click="chooseDestination(item.id)"><span class="destination-art">⌁</span><strong>{{ item.nom }}</strong><small>{{ item.region || 'Madagascar' }}</small><b>Voir les départs →</b></button><div v-if="!destinations.length" class="empty-panel">Les destinations seront bientôt disponibles.</div></div></section>
    <section id="stations" class="home-section stations-section"><div class="section-heading"><div><p class="travel-eyebrow">GARES ET COOPÉRATIVES</p><h2>Choisissez votre point de départ</h2><p>Chaque gare peut réunir plusieurs coopératives et leurs propres programmes.</p></div></div><div class="station-grid"><button v-for="item in gares.slice(0, 6)" :key="item.id" type="button" class="station-tile" @click="selectGare(item.id)"><span class="station-icon">⌖</span><span><strong>{{ item.nom }}</strong><small>{{ item.ville }} · {{ item.adresse || 'Adresse à confirmer' }}</small></span><b>{{ item.cooperatives.length }} coopérative{{ item.cooperatives.length > 1 ? 's' : '' }} →</b></button><div v-if="!gares.length" class="empty-panel">Les gares seront bientôt disponibles.</div></div></section>

    <section id="guide" class="travel-guide"><div class="guide-inner"><div><p class="travel-eyebrow">VOYAGER EN CONFIANCE</p><h2>Tout ce qu’il faut savoir avant le départ.</h2><p>Nous affichons uniquement les informations disponibles dans le programme de chaque coopérative.</p></div><div class="guide-grid"><article><span>01</span><strong>Comparez les horaires</strong><p>Date, heure, trajet et gare sont visibles avant de choisir.</p></article><article><span>02</span><strong>Réservez sans compte</strong><p>Le nom du réservataire suffit pour commencer.</p></article><article><span>03</span><strong>Payez une avance</strong><p>Une avance d’au moins 25 % valide la réservation.</p></article><article><span>04</span><strong>Gardez votre référence</strong><p>Votre billet est accessible après confirmation du paiement.</p></article></div></div></section>
    <section class="home-section faq-section"><div><p class="travel-eyebrow">BESOIN D’AIDE ?</p><h2>Les réponses aux questions courantes.</h2></div><div class="faq-list"><details><summary>Faut-il créer un compte pour réserver ?</summary><p>Non. Tout le monde peut réserver depuis le frontoffice. Un compte permet de retrouver son historique et ses billets.</p></details><details><summary>Quand la réservation devient-elle valide ?</summary><p>La réservation est en attente tant que l’avance n’est pas confirmée. Elle devient valide après la notification de paiement mobile money.</p></details><details><summary>Combien de temps avant le départ faut-il arriver ?</summary><p>Consultez les informations indiquées par la gare ou la coopérative dans votre confirmation.</p></details></div></section>
    <footer class="travel-footer"><div><RouterLink class="travel-brand" to="/"><span class="travel-brand-mark">C</span><strong>Coopérative</strong></RouterLink><p>La plateforme de réservation des voyages en taxi-brousse.</p></div><nav><RouterLink to="/conditions-voyage">Conditions de voyage</RouterLink><RouterLink to="/annulation">Annulation</RouterLink><RouterLink to="/confidentialite">Confidentialité</RouterLink><a href="#guide">Aide</a></nav><small>© 2026 Coopérative</small></footer>
  </main>
</template>

<style scoped>
